      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2, tmp3, tmp4

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[nonlocal_pcm_mf_medium] call nonlocal_pcm_assemble first")
         return
      end if
      state%ready = 1

      state%lam = lam
      state%eps_inf = eps_inf
      state%eps = eps
      state%eps_solute = eps_solute
      state%op2%npt = 3*npt
