      state%s16 = state%eps_solute*state%s15
      state%op2%c4 = state%s16
      state%s18 = state%s8*state%eps_solute
      state%op2%c5 = state%s18
      state%s20 = state%s14*state%eps_inf
      state%op2%c6 = state%s20
